+    // Process in blocks of 4 to improve instruction throughput and loop unrolling
+    // without breaking the single-threaded prefix sum dependency chain.
+    const int BLOCK_SIZE = 8;
+    size_t i = 0;
+    while (i < n) {
+        // Handle remaining elements if not a multiple of 4
+        size_t remaining = n - i;
+        size_t count = remaining < BLOCK_SIZE ? remaining : BLOCK_SIZE;
+        
+        // Unroll manually for clarity and control
+        for (size_t k = 0; k < count; ++k) {
+            int64_t val = in[i + k];
+            sum += val;
+            out[i + k] = sum;
+            hist[val & 255]++;
+        }
+        i += count;
     }
